"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import axiosInstance from "../../utils/axiosIntance";
export default function HomePage() {
  const router = useRouter();
  const [hasCharacter, setHasCharacter] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState(true);

  useEffect(() => {
    const userId = localStorage.getItem("user");
    const token =
      typeof window !== "undefined" ? localStorage.getItem("authToken") : null;

    if (!token) {
      router.replace("/login");
      return;
    }

    async function checkCharacterAndAuth() {
      try {
        setLoadingStatus(true);
        const characterResponse = await axiosInstance.get(
          `/characters/my-character/${userId}`
        );

        if (characterResponse.data) {
          setHasCharacter(true);
          router.replace("/dashboard");
        } else {
          setHasCharacter(false);
          router.replace("/create");
        }
      } catch (error: any) {
        if (error.response) {
          if (error.response.status === 404) {
            setHasCharacter(false);
            router.replace("/create");
          } else if (
            error.response.status === 401 ||
            error.response.status === 403
          ) {
            localStorage.removeItem("authToken");
            localStorage.removeItem("user");
            router.replace("/login");
          } else {
            console.error("Erro inesperado ao verificar personagem.");
            router.replace("/create");
          }
        } else {
          console.error("Erro inesperado ao verificar personagem.");
          router.replace("/create");
        }
      } finally {
      }
    }

    checkCharacterAndAuth();
  }, [router]);

  return <div>Carregando informações do jogo...</div>;
}
